import { intents } from "./simulation";
import { orderKeys, recordKeyStatus } from "./gemini-keys";
import { recordContextWeightSample } from "./memento-weight";
import { z } from "zod";
export const emotionKeys = ["curiosity", "tension", "trust", "comfort", "attraction"] as const;
export const initialEmotions = { curiosity: 72, tension: 58, trust: 8, comfort: 22, attraction: 12 };
export const emotionSchema = z.object(Object.fromEntries(emotionKeys.map(key => [key, z.number().int().min(0).max(100)])) as Record<typeof emotionKeys[number], z.ZodNumber>);
export type Emotions = z.infer<typeof emotionSchema>;
export function evolveEmotions(previous: Emotions, next: Emotions): Emotions {
    return Object.fromEntries(emotionKeys.map(key => [key, Math.max(0, Math.min(100, previous[key] + Math.max(-12, Math.min(key === "trust" || key === "attraction" ? 5 : 12, next[key] - previous[key]))))])) as Emotions;
}
export const decisionSchema = z.object({
    contribution:z.string().transform(text=>text.slice(0,180)).optional(),
    affectionAccepted: z.boolean(),
    intent: z.enum(intents),
    emotions: emotionSchema,
    reply: z.string().min(1).max(1600),
    thought: z.string().min(1).max(500).optional(),
    moveReason: z.string().max(120).optional(),
    stayAlone: z.boolean().optional(),
    nextRoom: z.enum(["salon","cuisine","chambre","bureau","jardin"]).nullable().optional(),
    nextIntent: z.enum(intents).nullable().optional(),
    acceptsNextRoom: z.boolean().optional(),
    mood: z.enum(["curieuse", "attentive", "paisible"]),
    activity: z.string().min(1).max(160),
    goal: z.string().min(1).max(160),
    action: z.enum(["none", "move", "talk"]),
    room: z.enum(["salon", "cuisine", "chambre", "bureau", "jardin"]),
    memory: z.string().min(1).max(500),
});
